CREATE TABLE marketing_coupon_template (id BIGINT PRIMARY KEY,name VARCHAR(128) NOT NULL,threshold_amount DECIMAL(18,2) NOT NULL DEFAULT 0,discount_amount DECIMAL(18,2) NOT NULL,total_qty INT NOT NULL,received_qty INT NOT NULL DEFAULT 0,start_at TIMESTAMP(3) NOT NULL,end_at TIMESTAMP(3) NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(3) NOT NULL);
CREATE TABLE marketing_user_coupon (id BIGINT PRIMARY KEY,template_id BIGINT NOT NULL,user_id BIGINT NOT NULL,status VARCHAR(32) NOT NULL,received_at TIMESTAMP(3) NOT NULL,used_order_no VARCHAR(64) NULL,used_at TIMESTAMP(3) NULL,UNIQUE KEY uk_user_coupon(template_id,user_id));
CREATE TABLE marketing_campaign (id BIGINT PRIMARY KEY,campaign_type VARCHAR(32) NOT NULL,name VARCHAR(128) NOT NULL,rule_json JSON NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(3) NOT NULL);
CREATE TABLE marketing_seckill_session (id BIGINT PRIMARY KEY,session_code VARCHAR(64) NOT NULL,start_at TIMESTAMP(3) NOT NULL,end_at TIMESTAMP(3) NOT NULL,status VARCHAR(32) NOT NULL,UNIQUE KEY uk_session_code(session_code));
CREATE TABLE marketing_seckill_item (id BIGINT PRIMARY KEY,session_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,price DECIMAL(18,2) NOT NULL,stock_qty INT NOT NULL,limit_per_user INT NOT NULL DEFAULT 1,status VARCHAR(32) NOT NULL,UNIQUE KEY uk_seckill_sku(session_id,sku_id));
CREATE TABLE marketing_seckill_order (id BIGINT PRIMARY KEY,session_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,user_id BIGINT NOT NULL,quantity INT NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uk_seckill_user(session_id,sku_id,user_id));
